  "summary": "The codebase contains critical performance risks due to unbounded queries and inefficient raw SQL usage, alongside security vulnerabilities regarding missing authorization. The overall health is poor, requiring refactoring to use the Django ORM, implementing pagination, and adding proper access control.",
  "fixed_code": "from django.http import JsonResponse, HttpRequest\nfrom django.views.decorators.http import require_GET\nfrom django.contrib.auth.decorators import login_required\nfrom .models import Article, Order\n\nDEFAULT_LIMIT = 10\nMAX_LIMIT = 50\n\n@login_required\n@require_GET\ndef articles_by_author(request: HttpRequest) -> JsonResponse:\n    \"\"\"Returns a list of articles for a given author with pagination.\"\"\"\n    author = request.GET.get(\"author\", \"\")\n    limit = min(int(request.GET.get(\"limit\", DEFAULT_LIMIT)), MAX_LIMIT)\n    articles = Article.objects.filter(author=author).select_related(\"category\")[:limit]\n    return JsonResponse({\"articles\": [{\"id\": a.id, \"title\": a.title, \"category\": a.category.name if a.category else None} for a in articles]})\n\n@login_required\n@require_GET\ndef article_count(request: HttpRequest) -> JsonResponse:\n    \"\"\"Returns the count of articles for a specific author.\"\"\"\n    author = request.GET.get(\"author\", \"\")\n    count = Article.objects.filter(author=author).count()\n    return JsonResponse({\"count\": count})\n\ndef order_summaries():\n    \"\"\"Returns a paginated list of order summaries.\"\"\"\n    return [\n        {\"id\": o.id, \"customer\": o.customer.name, \"total\": o.total}\n        for o in Order.objects.select_related(\"customer\")[:MAX_LIMIT]\n    ]"
}
